<?php declare(strict_types=1); namespace Modules\PromptEngine\Services\ImageProviders; use Illuminate\Support\Facades\Http; use RuntimeException; use Modules\PromptEngine\Interfaces\ImageGenerationProviderInterface; final class GeminiImageProvider implements ImageGenerationProviderInterface { public function name():string{return 'gemini';} public function generate(string $prompt,string $aspectRatio):array{$cfg=config('promptengine.config.image_generation');if(empty($cfg['gemini']['api_key']))throw new RuntimeException('Gemini image provider is not configured.');$url='https://generativelanguage.googleapis.com/v1beta/models/'.$cfg['gemini']['model'].':generateContent';$response=Http::timeout($cfg['timeout'])->retry($cfg['retries'],300)->withHeaders(['x-goog-api-key'=>$cfg['gemini']['api_key']])->post($url,['contents'=>[['parts'=>[['text'=>$prompt]]]],'generationConfig'=>['responseModalities'=>['TEXT','IMAGE']]]);$response->throw();foreach($response->json('candidates.0.content.parts',[]) as $part){$inline=$part['inlineData']??$part['inline_data']??null;if($inline)return ['bytes'=>base64_decode($inline['data'],true),'mime_type'=>$inline['mimeType']??$inline['mime_type']??'image/png'];}throw new RuntimeException('Gemini returned no image data.');} }
